import React from 'react'
import {Link, matchPath} from 'react-router-dom'
import logo from '../../assets/Logo/Logo-Full-Light.png'
import {NavbarLinks} from "../../data/navbar-links"
import { useLocation } from 'react-router-dom'
import { useSelector} from 'react-redux'
import { FaShoppingCart } from "react-icons/fa";
import ProfileDropDown from '../core/Auth/ProfileDropDown'
import { apiconnector } from '../../services/apiconnector'
import { categories} from '../../services/api'
import { useState,useEffect } from 'react'
import { IoIosArrowDropdownCircle } from "react-icons/io";




const Navbar = () => {

  const {token} = useSelector((state) => state.auth);
  const {user} = useSelector((state) => state.profile);
  const {totalItems} = useSelector((state) => state.cart);
  const location = useLocation();

  const [subLinks, setSubLinks] = useState([]);



  useEffect(() => {
    ;(async () => {
      setLoading(true)
      try {
        const res = await apiConnector("GET", categories.CATEGORIES_API)
        setSubLinks(res.data.data)
      } catch (error) {
        console.log("Could not fetch Categories.", error)
      }
      setLoading(false)
    })()
  }, [])
  const matchRoute = (route) => {
    return matchPath({path:route}, location.pathname);
  }
  return (
    <div className='flex h-14 items-center border-b-[1px] border-b-richblack-700'>
      <div className='flex w-11/12 max-w-maxContent items-center justify-between'>

      <Link to = "/">
      <img src={logo} width={160} height={42} loading='lazy'/>
      </Link>

      <nav>
        <ul className='flex gap-x-6 text-richblack-25'>
          {
            NavbarLinks.map((link , index) => (
              <li key={index}>
                {link.title === "Catalog" ? (
                    <div className='relative flex items-center  gap-2 group'>
                      <p>{link.title}</p>
                      <IoIosArrowDropdownCircle />

                      <div className='invisible absolute left-[50%] translate-x-[-50%] translate-y-[80%] top-[50%] flex flex-col
                      rounded-md bg-richblack-5 text-richblack-900 opacity-0 transition-all duration-200
                      group-hover:visible group-hover:opacity-100 lg:w-[300px]'>

                        <div className='absolute left-[50%] top-0
                        translate-x-[80%]
                        translate-y-[-45%] h-6 w-6 rotate-45 rounded bg-richblack-5'>

                        </div>

                        {subLinks
                              ?.filter(
                                (subLink) => subLink?.courses?.length > 0
                              )
                              ?.map((subLink, i) => (
                                <Link
                                  to={`/catalog/${subLink.name
                                    .split(" ")
                                    .join("-")
                                    .toLowerCase()}`}
                                  className="rounded-lg bg-transparent py-4 pl-4 hover:bg-richblack-50"
                                  key={i}
                                >
                                  <p>{subLink.name}</p>
                                </Link>
                              ))}

                      </div>

                    </div>
                ) : (
                  <Link to = {link?.path}>
                    <p className= {`${matchRoute(link?.path) ? "text-yellow-25":"text-richblack-25"}`}>
                      {link.title}
                    </p>

                  </Link>
                )
              }
              </li>
            ))
          }

        </ul>
      </nav>

      <div className='flex gap-x-4 items-center'>

        {
          user && user?.accountType != "Instructor" && (
            <Link to ="/dashboard/cart" className='relative'>
              <FaShoppingCart />
              {
                totalItems > 0 && (
                  <span>
                    {totalItems}
                  </span>
                )
              }

            </Link>
          )
        }
        {
          token === null && (
            <Link to = "/login">
              <button className='border border-richblack-700 bg-richblack-800 px-[12px] py-[8px]
              text-richblack-100 rounded-md'>
                Login
              </button>
            </Link>
          )
        }
        {
          token === null && (
            <Link to = "/signup">
              <button className='border border-richblack-700 bg-richblack-800 px-[12px] py-[8px]
              text-richblack-100 rounded-md'>
                Sign up
              </button>
            </Link>
          )
        }
        {
          token != null && <ProfileDropDown/>
        }

      </div>
      </div>
    </div>
  )
}

export default Navbar
